-- Disposable database with fictional member seed. Temporary identities and writes roll back.
begin;
insert into auth.users(id,email,email_confirmed_at) select ('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,'onboarding-'||n||'@example.invalid',now() from generate_series(101,108)n;
insert into auth.sessions(id,user_id,created_at) select ('aaaaaaaa-aaaa-4aaa-8aaa-'||lpad(n::text,12,'0'))::uuid,('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,now()-interval '1 hour' from generate_series(101,108)n;
insert into app_private.account_links(member_id,auth_user_id,username) select ('44444444-4444-4444-8444-'||lpad(n::text,12,'0'))::uuid,('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,'onboarding_'||n from generate_series(101,108)n;
create function pg_temp.assert_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.assert_denied(statement text,code text,label text) returns void language plpgsql as $$declare actual text;begin begin execute statement;exception when others then get stacked diagnostics actual=returned_sqlstate;end;if actual is distinct from code then raise exception 'FAIL: %, expected %, got %',label,code,actual;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.login(n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub','99999999-9999-4999-8999-'||lpad(n::text,12,'0'),true);perform set_config('request.jwt.claims',jsonb_build_object('sub','99999999-9999-4999-8999-'||lpad(n::text,12,'0'),'session_id','aaaaaaaa-aaaa-4aaa-8aaa-'||lpad(n::text,12,'0'))::text,true);end $$;
set local role service_role;
select public.submit_access_request('isla@example.invalid','Isla Example');select public.submit_access_request('ISLA@EXAMPLE.INVALID','Isla Example');
reset role;select pg_temp.assert_ok((select count(*)=1 from app_private.access_requests),'pending access requests deduplicate normalized email');
select pg_temp.login(107);set local role authenticated;
select pg_temp.assert_ok(jsonb_array_length(public.member_workspace()->'onboarding'->'requests')=0,'ordinary member cannot view access requests');
select pg_temp.assert_ok(jsonb_array_length(public.member_workspace()->'onboarding'->'accounts')=0,'ordinary member cannot view sign-in account directory');
select pg_temp.assert_denied($q$select public.admin_command('account.access','{"memberId":"44444444-4444-4444-8444-000000000108","enabled":"false","reason":"Unauthorized attempt"}',gen_random_uuid())$q$,'42501','ordinary member cannot suspend another account');
reset role;select pg_temp.login(105);set local role authenticated;
select pg_temp.assert_ok(jsonb_array_length(public.member_workspace()->'onboarding'->'requests')=1,'explicit organizational authority sees pending request');
select pg_temp.assert_denied($q$select public.admin_command('organization.archive','{"id":"33333333-3333-4333-8333-000000000001","kind":"unit","reason":"Occupied unit archival attempt"}',gen_random_uuid())$q$,'23514','occupied unit cannot be archived');
select pg_temp.assert_denied($q$select public.admin_command('account.access','{"memberId":"44444444-4444-4444-8444-000000000108","enabled":"false","reason":"Organizational only role"}',gen_random_uuid())$q$,'42501','organizational authority does not imply technical suspension authority');
select pg_temp.assert_denied($q$select public.admin_command('organization.rename','{"id":"66666666-6666-4666-8666-000000000001","kind":"department","name":"Changed","reason":"Organizational only role"}',gen_random_uuid())$q$,'42501','organizational authority cannot rename departments');
select public.admin_command('organization.rename','{"id":"33333333-3333-4333-8333-000000000001","kind":"unit","name":"Demo Unit Renamed","reason":"Verified organizational correction"}',gen_random_uuid());
reset role;select pg_temp.assert_ok(exists(select 1 from public.church_units where id='33333333-3333-4333-8333-000000000001' and name='Demo Unit Renamed'),'unit rename preserves existing identifier');
select pg_temp.login(104);set local role authenticated;
select pg_temp.assert_ok(jsonb_array_length(public.member_workspace()->'onboarding'->'accounts')=8,'technical administrator sees account-only projection');
select pg_temp.assert_denied($q$select public.admin_command('account.access','{"memberId":"44444444-4444-4444-8444-000000000104","enabled":"false","reason":"Self suspension attempt"}',gen_random_uuid())$q$,'42501','technical administrator cannot suspend self');
select public.admin_command('account.access','{"memberId":"44444444-4444-4444-8444-000000000108","enabled":"false","reason":"Verified account suspension"}',gen_random_uuid());
reset role;select pg_temp.login(108);set local role authenticated;
select pg_temp.assert_ok(public.my_membership_id() is null,'technical suspension immediately denies existing session');
reset role;select pg_temp.login(105);set local role authenticated;
select public.member_command('member.status','{"memberId":"44444444-4444-4444-8444-000000000108","status":"active","reason":"Membership stays active"}',gen_random_uuid());
reset role;select pg_temp.assert_ok(not(select technical_enabled from app_private.account_links where member_id='44444444-4444-4444-8444-000000000108'),'membership activation cannot override technical suspension');
select pg_temp.assert_ok((select status='active' from public.members where id='44444444-4444-4444-8444-000000000108'),'technical suspension does not change membership status');
set constraints all immediate;
rollback;
